package dev.arabicgames.phone;
import android.content.Context;import org.json.JSONArray;import java.util.*;
/** Conservative dialogue-mode filtering of dashboard labels and observed credit names. */
final class CaptionNoise {
 private static volatile Set<String> credits;
 private static final Set<String> UI=new HashSet<>(Arrays.asList("xbox insider hub","grand theft auto vi","red dead redemption 2","game","pass","game pass","same","resume","select","game details","pre-ordered","play","the store","e the store","recent achievements","recent achievemenls","optimised for xbox series xs","play fallout 76","play with game pass","play with game pas s","q","in"));
 private static String key(String s){return s.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}
 private static Set<String> credits(Context c){if(credits!=null)return credits;Set<String> set=new HashSet<>();try(java.io.InputStream in=c.getAssets().open("known-credit-lines.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray a=new JSONArray(out.toString("UTF-8"));for(int i=0;i<a.length();i++)set.add(key(a.getString(i)));}catch(Exception ignored){}try{java.io.File cached=new java.io.File(c.getFilesDir(),"community-reviewed.json");if(cached.isFile()&&cached.length()<1_000_000){JSONArray ignored=new org.json.JSONObject(new String(java.nio.file.Files.readAllBytes(cached.toPath()),java.nio.charset.StandardCharsets.UTF_8)).optJSONArray("ignored_sources");if(ignored!=null&&ignored.length()<1000)for(int i=0;i<ignored.length();i++){String value=ignored.getString(i);if(value.length()<=200)set.add(key(value));}}}catch(Exception ignored){}credits=Collections.unmodifiableSet(set);return credits;}
 static void invalidate(){credits=null;}
 static String clean(Context c,String text,String game){boolean photo=text.toLowerCase(Locale.ROOT).contains("photo mode select");boolean dashboard=text.toLowerCase(Locale.ROOT).contains("xbox insider hub")||text.toLowerCase(Locale.ROOT).contains("optimised for xbox");StringBuilder out=new StringBuilder();for(String raw:text.split("\\n")){String line=raw.trim(),k=key(line);if(photo&&k.matches("(?:gress|[49]er|ine|ial club|tings|progress|player|online|social club|settings)"))continue;if(line.isEmpty()||UI.contains(k)||credits(c).contains(k)||k.matches("photo mode select.*")||line.matches("[\\d\\s).]+")||line.matches("(?i)(?:NZ\\$|US\\$|\\$)\\s*[\\d.,]+")||k.matches("[0-9]+ gold bars"))continue;if(dashboard&&k.matches("(?:[a-z0-9 ]{0,25}game pass|apparel, and action threaded acr|aspects of jason and lucia.s stor)"))continue;if(out.length()>0)out.append('\n');out.append(line);}
  String result=out.toString();if(GameNames.key(game).equals("gta6"))result=result.replace("this quy?","this guy?").replace("prison quard","prison guard").replace("the timne to make","the time to make").replace("Idon't like to do this","I don't like to do this").replace("Il just go out on my own.","I'll just go out on my own.");return result;
 }
}
